'use strict';
const $=id=>document.getElementById(id);
const REGION_INFO={Africa:{center:[20,7],symbol:'M7 4l9-2 8 6-3 7-4 2-2 9-5-3-2-9-4-4z'},Asia:{center:[85,28],symbol:'M3 9l6-5 8 1 5-3 7 7-4 7-6-1-3 10-4-9-6 2z'},Europe:{center:[19,48],symbol:'M6 18l3-6-2-6 6-3 1 9 5-4 6 3 1 9-7 3-4-6-4 6z'},'North America':{center:[-100,30],symbol:'M3 5l12-2 10 5-4 7-7 1 2 6 7 4-7 2-7-8-3-8z'},'South America':{center:[-60,-18],symbol:'M9 3l10 2 5 8-4 4-4 10-4 2-1-13-6-6z'},Oceania:{center:[153,-19],symbol:'M3 15l7-5 8 2 2 9-8 3-7-2zM22 5l5 4M24 22l4 4'},World:{center:[15,15],symbol:''}};
const STORAGE='atlas-countries-v2';
let countryFacts=null,pendingProfileId=null;
let countries=[],geo,byId={},state,records={},map,ready=false,selected=null,hoverCode='',pendingRegion='',spinning=false,lastFrame=0,raf=0;
let reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function readSaved(){try{return JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{return null}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({state,records}))}catch{}}
function regionCountries(region){return countries.filter(c=>region==='World'||c.continent===region)}
function shuffled(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function renderRegions(){const paths=Object.entries(REGION_INFO);$('regions').innerHTML=paths.map(([name,r])=>`<button class="region ${state?.region===name?'active':''} ${records[name]?.completed?'complete':''}" data-region="${name}" aria-pressed="${state?.region===name}"><svg viewBox="0 0 32 32" aria-hidden="true">${r.symbol?`<path d="${r.symbol}"/>`:'<circle cx="16" cy="16" r="12"/><ellipse cx="16" cy="16" rx="6" ry="12"/><path d="M4 16h24"/>'}</svg><strong>${name==='World'?'The whole world':name}</strong><small>${regionCountries(name).length} countries ${records[name]?.completed?'· ✓':''}</small></button>`).join('');$('collectionProgress').textContent=`${paths.filter(([n])=>n!=='World'&&records[n]?.completed).length} / 6 continents completed`;$('regions').querySelectorAll('button').forEach(b=>b.onclick=()=>requestRegion(b.dataset.region));}
function requestRegion(region){if(!ready)return;if(state&&!state.complete&&(state.cursor>0||state.results.length||selected)){pendingRegion=region;$('switchDialog').showModal()}else start(region)}
function start(region,ids){pendingProfileId=null;stopSpin();selected=null;state={region,deck:shuffled(ids||regionCountries(region).map(c=>c.id)),cursor:0,results:[],flagOnly:state?.flagOnly||false,complete:false,practice:!!ids};save();renderRegions();render();recenter();}
function target(){return byId[state.deck[state.cursor]]}function revealed(){return state.results.length>state.cursor}
function setText(id,text){$(id).textContent=text}
function setFlag(country){$('flag').src=`flags/${country.code}.png`;$('flag').alt=state.flagOnly&&!revealed()?'Flag of the country to find':`Flag of ${country.name}`;}
function render(){if(!state)return;selected=null;$('review').hidden=true;$('countryFacts').hidden=true;renderRegions();paintCountries();let count=state.deck.length,done=state.results.length,correct=state.results.filter(r=>r.correct).length,percent=Math.round(done/count*100);setText('regionLabel',`${state.region.toUpperCase()} ${state.practice?'PRACTICE':'EXPEDITION'}`);setText('round',state.complete?'EXPEDITION COMPLETE':`COUNTRY ${String(state.cursor+1).padStart(2,'0')} / ${count}`);setText('percent',`${percent}%`);$('progress').style.width=`${percent}%`;$('found').innerHTML=`${correct}<span> / ${count}</span>`;setText('accuracy',done?Math.round(correct/done*100)+'%':'—');let streak=0;for(let i=state.results.length-1;i>=0&&state.results[i].correct;i--)streak++;setText('streak',streak);setText('best',records[state.region]?.best!=null?records[state.region].best+'%':'—');$('flagMode').setAttribute('aria-pressed',String(state.flagOnly));$('flagMode').disabled=state.complete;$('feedback').className='feedback';$('feedback').replaceChildren();$('submit').disabled=!ready;$('skip').disabled=!ready||state.complete||revealed();$('flagFrame').hidden=state.complete;$('instruction').innerHTML='Spin the globe. Find the country.<br>Click its shape to select your answer.';setText('panelNote','Answer to discover languages, beliefs & government.');
 if(state.complete){setText('questionEyebrow',state.practice?'PRACTICE COMPLETE':'EXPEDITION COMPLETE');setText('countryName',correct===count?'A world well known.':'A little closer to the world.');setText('instruction',`You identified ${correct} of ${count} countries correctly. ${correct===count?'Every country, found. Beautifully done.':'Every discovery brings you further.'}`);setText('selection',`${Math.round(correct/count*100)}% accuracy · ${count} countries explored`);$('submit').innerHTML='Explore again <span>↗</span>';setText('mapMessage','Your expedition is complete. Keep your curiosity.');showReview();return}
 const c=target();setFlag(c);setText('questionEyebrow',state.flagOnly&&!revealed()?'FOLLOW THE FLAG':'FIND THIS COUNTRY');setText('countryName',state.flagOnly&&!revealed()?'Where does this flag belong?':c.name);$('submit').innerHTML=revealed()?(state.cursor===count-1?'See expedition results <span>↗</span>':'Next country <span>↗</span>'):'Check answer <span>↗</span>';$('submit').disabled=!ready||!revealed();setText('selection','◎ Select a country on the globe');setText('mapMessage',ready?'Drag to rotate · Scroll to zoom · Click a country':'Preparing your expedition…');
 if(revealed()){showCountryFacts(c);const r=state.results[state.cursor];setText('selection',r.guess?`Your selection: ${byId[r.guess]?.name||r.guess}`:'You skipped this country');$('feedback').className='feedback visible'+(r.correct?'':' wrong');const strong=document.createElement('strong');strong.textContent=r.correct?'A perfect find.':r.guess?'A new place to remember.':'One for your next adventure.';const detail=document.createElement('span');detail.textContent=`${c.name} · ${c.continent}${c.capital?' · Capital: '+c.capital:''}`;const profileButton=document.createElement('button');profileButton.id='feedbackProfile';profileButton.className='feedback-profile';profileButton.textContent='Country shape & discovery profile ↗';profileButton.disabled=!countryFacts?.countries?.[c.id];profileButton.onclick=openCountryProfile;$('feedback').append(strong,detail,profileButton);if(!r.correct){const locationButton=document.createElement('button');locationButton.className='feedback-profile';locationButton.textContent='Show correct location ↗';locationButton.onclick=revealCorrectLocation;$('feedback').append(locationButton)}setText('instruction',r.correct?'Country identified. Keep exploring.':'The correct country is highlighted in green.');setText('mapMessage',r.correct?`✓ ${c.name} — found`:`${c.name} is highlighted in green`);setText('panelNote','Green: destination · Coral: missed selection.');}
}
function showReview(){const missed=state.results.filter(r=>!r.correct).map(r=>byId[r.id]);if(!missed.length){$('review').hidden=true;return}$('review').hidden=false;$('missedFlags').replaceChildren();for(const c of missed){let el=document.createElement('span');el.className='missed-country';let img=document.createElement('img');img.src=`flags/${c.code}.png`;img.alt='';el.append(img,document.createTextNode(c.name));$('missedFlags').append(el)}}
function revealCorrectLocation(){if(!ready||state.complete||!revealed())return;stopSpin();const c=target();map.flyTo({center:c.center,zoom:Math.max(map.getZoom(),c.area<3000?4:2.2),duration:reduced?0:1300,essential:false});setText('mapMessage',`Correct location: ${c.name} · highlighted in green`)}
function check(skip=false){if(!ready||state.complete||revealed()||(!selected&&!skip))return;stopSpin();const c=target();state.results.push({id:c.id,guess:skip?null:selected,correct:!skip&&selected===c.id});save();render();if(state.results[state.cursor].correct){pendingProfileId=c.id;if(countryFacts?.countries?.[c.id]){pendingProfileId=null;openCountryProfile()}}else{revealCorrectLocation()}}
function next(){pendingProfileId=null;if($('profileDialog').open)$('profileDialog').close();if(state.complete){start(state.region);return}if(!revealed()){check();return}if(state.cursor===state.deck.length-1){state.complete=true;if(!state.practice){let accuracy=Math.round(state.results.filter(r=>r.correct).length/state.deck.length*100);records[state.region]={completed:true,best:Math.max(accuracy,records[state.region]?.best||0)}}save();render();}else{state.cursor++;selected=null;save();render();}}
function paintCountries(){if(!ready||!state)return;const correct=state.results.filter(r=>r.correct).map(r=>r.id);const r=revealed()?state.results[state.cursor]:null;const active=state.region==='World'?true:['==',['get','continent'],state.region];const fill=['case',['==',['get','code'],selected||''],'#7baf9d',...(r?[['==',['get','code'],r.id],'#70d2ad',...(r.guess&&!r.correct?[['==',['get','code'],r.guess],'#b66d63']:[])]:[]),['in',['get','code'],['literal',correct]],'#3d7a68',active,'#304c50','#1a2c35'];map.setPaintProperty('countries','fill-color',fill);map.setPaintProperty('countries','fill-opacity',['case',['==',['get','code'],hoverCode||''],.98,.87]);map.setPaintProperty('borders','line-color',['case',['==',['get','code'],selected||''],'#d1e8bb','#72918e']);map.setPaintProperty('borders','line-width',['case',['==',['get','code'],selected||''],1.6,.55]);map.setPaintProperty('small-countries','circle-color',fill);map.setPaintProperty('small-countries','circle-stroke-color',['case',['==',['get','code'],selected||''],'#edfad4',...(r?[['==',['get','code'],r.id],'#9ff8cd']:[]),'#98b9ae']);map.setFilter('small-countries',state.region==='World'?null:['==',['get','continent'],state.region]);}
function chooseAt(point){if(!ready||state.complete||revealed())return;stopSpin();const hits=map.queryRenderedFeatures(point,{layers:['small-countries','countries']});const hit=hits.find(f=>byId[f.properties.code]&&(state.region==='World'||byId[f.properties.code].continent===state.region));if(!hit){setText('mapMessage','Choose a country in this expedition. Zoom in for small countries.');return}selected=hit.properties.code;paintCountries();setText('selection',`◎ Selected: ${byId[selected].name}`);$('submit').disabled=false;setText('mapMessage','Click another country to change your selection.');}
function baseZoom(){const fill=state?.region==='World'?.96:.83;return Math.log2(Math.max(200,Math.min($('map').clientWidth*fill,$('map').clientHeight*fill))/210)}
function recenter(){if(!ready)return;stopSpin();map.flyTo({center:REGION_INFO[state.region].center,zoom:baseZoom(),pitch:0,bearing:0,duration:reduced?0:1300,essential:false})}
function stopSpin(){spinning=false;cancelAnimationFrame(raf);$('spin').setAttribute('aria-pressed','false');lastFrame=0}
function rotate(now){if(!spinning)return;if(lastFrame){const c=map.getCenter();map.jumpTo({center:[c.lng+(now-lastFrame)*.003,c.lat]})}lastFrame=now;raf=requestAnimationFrame(rotate)}
function fail(message){$('mapError').hidden=false;setText('mapError',message);$('submit').disabled=true;$('skip').disabled=true;setText('mapMessage','The globe is unavailable. Reload to try again.')}
function graticule(){const features=[];for(let lng=-180;lng<180;lng+=30){features.push({type:'Feature',geometry:{type:'LineString',coordinates:Array.from({length:177},(_,i)=>[lng,i-88])}})}for(let lat=-60;lat<=60;lat+=30){features.push({type:'Feature',geometry:{type:'LineString',coordinates:Array.from({length:361},(_,i)=>[i-180,lat])}})}return {type:'FeatureCollection',features}}

async function loadCountryFacts(){try{const r=await fetch('facts.json');if(!r.ok)throw Error('Facts unavailable');countryFacts=await r.json();if(state&&!state.complete&&revealed()){showCountryFacts(target());if(pendingProfileId===target().id&&state.results[state.cursor].correct){pendingProfileId=null;openCountryProfile()}}}catch{countryFacts=null;if(state&&!state.complete&&revealed())showCountryFacts(target())}}
function factExcerpt(value,limit=370){if(value.length<=limit)return value;const part=value.slice(0,limit).replace(/\s+\S*$/,'');const date=value.match(/\((?:[^()]*(?:19|20)\d{2}[^()]*)\)/g)?.at(-1);return part+'…'+(date&&!part.includes(date)?' '+date:'')}
function showCountryFacts(c){const f=countryFacts?.countries?.[c.id];$('countryFacts').hidden=false;setText('factsTitle',`A closer look at ${c.name}.`);$('factsOutline').src=`outlines/${c.code}.svg`;$('factsOutline').alt=`Simplified outline of ${c.name}`;$('fullProfile').disabled=!f;const feedbackLink=$('feedbackProfile');if(feedbackLink)feedbackLink.disabled=!f;if(!f){for(const id of ['factLanguages','factReligions','factGovernment'])setText(id,countryFacts?'Profile unavailable.':'Loading country profile…');setText('factSourceNote',countryFacts?'This profile is not available.':'If the facts do not load, refresh the page; your quiz progress is saved.');return}setText('factLanguages',factExcerpt(f.languages));setText('factReligions',factExcerpt(f.religions));setText('factGovernment',factExcerpt(f.government));setText('factSourceNote','Source: World Factbook archive & linked references · Government classifications are archival; estimate dates are retained. Open the full profile for notes and sources.')}
function openCountryProfile(){if(!state||state.complete||!revealed())return;const c=target(),f=countryFacts?.countries?.[c.id];if(!f)return;stopSpin();setText('profileEyebrow',state.results[state.cursor].correct?'✓ CORRECT · COUNTRY DISCOVERED':'BEYOND THE BORDERS');setText('profileTitle',c.name);setText('profileRegion',c.continent);$('profileOutline').src=`outlines/${c.code}.svg`;$('profileOutline').alt=`Simplified main outline of ${c.name}`;$('profileMetrics').replaceChildren();for(const [label,value]of [['Capital',c.capital||'Not specified'],['Population',f.population],['Area',c.area.toLocaleString()+' km²'],['Currency',f.currency]]){const cell=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value||'Not specified';cell.append(dt,dd);$('profileMetrics').append(cell)}setText('profileNext',state.cursor===state.deck.length-1?'See expedition results ↗':'Next country ↗');$('profileFlag').src=`flags/${c.code}.png`;$('profileFlag').alt=`Flag of ${c.name}`;$('profileBody').replaceChildren();for(const [heading,value,note]of [['Location',f.location,''],['Climate',f.climate,''],['Terrain',f.terrain,''],['Languages spoken',f.languages,f.languageNote],['Religions & beliefs',f.religions,f.religionNote],['Government type · reference profile',f.government,f.governmentNote]]){const section=document.createElement('section'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=heading;p.textContent=value;section.append(h,p);if(note){const n=document.createElement('p');n.className='profile-note';n.textContent=note;section.append(n)}$('profileBody').append(section)}$('profileSources').replaceChildren();const heading=document.createElement('h3');heading.textContent='Sources & context';$('profileSources').append(heading);for(const source of [...f.sources,{label:'Country outline · Natural Earth (main territory; distant islands or overseas territories may be omitted)',url:'https://github.com/datasets/geo-countries'}]){const link=document.createElement('a');link.href=source.url;link.target='_blank';link.rel='noreferrer';link.textContent=source.label+' ↗';$('profileSources').append(link)}setText('profileDate','Reference data retrieved October 26, 2026. '+countryFacts.note);$('profileDialog').showModal();$('profileDialog').scrollTop=0}

async function init(){try{const responses=await Promise.all([fetch('countries.json'),fetch('world.geojson')]);if(responses.some(r=>!r.ok))throw Error('Country files unavailable');[countries,geo]=await Promise.all(responses.map(r=>r.json()));byId=Object.fromEntries(countries.map(c=>[c.id,c]));const saved=readSaved();records=saved?.records&&typeof saved.records==='object'?saved.records:{};const s=saved?.state;if(s&&REGION_INFO[s.region]&&Array.isArray(s.deck)&&s.deck.length&&s.deck.every(id=>byId[id])&&new Set(s.deck).size===s.deck.length&&Array.isArray(s.results)&&Number.isInteger(s.cursor)&&s.cursor>=0&&s.cursor<s.deck.length&&s.results.length<=s.deck.length){state=s}else{state={region:'Africa',deck:shuffled(regionCountries('Africa').map(c=>c.id)),cursor:0,results:[],flagOnly:false,complete:false,practice:false}}
 render();loadCountryFacts();mapboxgl.accessToken='pk.eyJ1Ijoicm9uZG9taW5ndWUiLCJhIjoiYTM4ODdRdyJ9.jcyNgQQolgrKfs6SKBXNJw';map=new mapboxgl.Map({container:'map',style:{version:8,sources:{},layers:[{id:'ocean',type:'background',paint:{'background-color':'#122b38'}}]},center:REGION_INFO[state.region].center,zoom:baseZoom(),minZoom:-1.5,maxZoom:8,projection:'globe',attributionControl:false,renderWorldCopies:false,dragRotate:false});map.addControl(new mapboxgl.AttributionControl({compact:true,customAttribution:'Boundaries: Natural Earth'}),'bottom-right');map.on('load',()=>{map.setFog({color:'#284850','high-color':'#1b3545','space-color':'#0b1318','horizon-blend':.12,'star-intensity':.16});map.addSource('grid',{type:'geojson',data:graticule()});map.addLayer({id:'grid',type:'line',source:'grid',paint:{'line-color':'#52737d','line-opacity':.16,'line-width':.6}});map.addSource('world',{type:'geojson',data:geo,tolerance:.15});map.addLayer({id:'countries',type:'fill',source:'world',paint:{'fill-color':'#304c50','fill-opacity':.87}});map.addLayer({id:'borders',type:'line',source:'world',paint:{'line-color':'#72918e','line-width':.55,'line-opacity':.6}});map.addSource('small',{type:'geojson',data:{type:'FeatureCollection',features:countries.filter(c=>c.area<3000||!geo.features.some(f=>f.properties.code===c.id)).map(c=>({type:'Feature',properties:{code:c.id,continent:c.continent},geometry:{type:'Point',coordinates:c.center}}))}});map.addLayer({id:'small-countries',type:'circle',source:'small',paint:{'circle-radius':['interpolate',['linear'],['zoom'],0,4,3,6,6,9],'circle-color':'#304c50','circle-stroke-color':'#98b9ae','circle-stroke-width':1,'circle-opacity':.95}});ready=true;render();map.getCanvas().setAttribute('aria-label','Quiz globe. Arrow keys rotate. Plus and minus zoom. Enter selects the country at the centre.');map.on('click',e=>chooseAt(e.point));map.on('mousemove',e=>{if(state.complete||revealed())return;const hit=map.queryRenderedFeatures(e.point,{layers:['small-countries','countries']}).find(f=>byId[f.properties.code]&&(state.region==='World'||byId[f.properties.code].continent===state.region));const code=hit?.properties.code||'';map.getCanvas().style.cursor=code?'pointer':'grab';if(code!==hoverCode){hoverCode=code;paintCountries()}});map.on('dragstart',stopSpin);map.on('zoomstart',e=>{if(e.originalEvent)stopSpin()});map.getCanvas().addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();chooseAt({x:$('map').clientWidth/2,y:$('map').clientHeight/2})}});});map.on('error',e=>{if(!ready)fail('The globe could not load. Check your connection, reload the page, and make sure WebGL is enabled.')});}catch(e){fail('We couldn’t prepare the globe. Check your connection and reload the page. Your saved progress is kept.')}}
$('profileNext').onclick=next;$('profileKeepExploring').onclick=()=>$('profileDialog').close();$('fullProfile').onclick=openCountryProfile;$('closeProfile').onclick=()=>$('profileDialog').close();
$('submit').onclick=next;$('skip').onclick=()=>check(true);$('flagMode').onclick=()=>{if(!state||state.complete)return;state.flagOnly=!state.flagOnly;save();const prior=selected;render();if(prior&&!revealed()){selected=prior;paintCountries();setText('selection',`◎ Selected: ${byId[selected].name}`);$('submit').disabled=false}};$('zoomIn').onclick=()=>{stopSpin();map?.zoomIn()};$('zoomOut').onclick=()=>{stopSpin();map?.zoomOut()};$('reset').onclick=recenter;$('spin').onclick=()=>{if(!ready)return;if(spinning){stopSpin();return}spinning=true;$('spin').setAttribute('aria-pressed','true');lastFrame=0;raf=requestAnimationFrame(rotate)};$('how').onclick=()=>{stopSpin();$('help').showModal()};$('closeHelp').onclick=$('helpDone').onclick=()=>$('help').close();$('sources').onclick=()=>$('notes').showModal();$('closeNotes').onclick=()=>$('notes').close();$('regionsButton').onclick=()=>$('regions').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'});$('cancelSwitch').onclick=()=>$('switchDialog').close();$('confirmSwitch').onclick=()=>{$('switchDialog').close();start(pendingRegion)};$('retryMissed').onclick=()=>{const ids=state.results.filter(r=>!r.correct).map(r=>r.id);if(ids.length)start(state.region,ids)};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpin()});init();
